// 1. Dynamic Polymorphism (Runtime)
// High overhead due to vtable (vptr + array of function pointers)

class Shape {
    // Adds hidden vptr (Virtual Pointer) to object layout
    virtual void draw() const = 0;
};

class Circle : public Shape {
    void draw() const override { /* Indirect call via vtable */ }
};

// Cost: Runtime lookup, cache misses (vtable access), memory overhead (vptr)
// Performance: Slower function resolution

// ---

// 2. Static Polymorphism (Compile-Time via Templates)
// Zero overhead, specialization resolved at compile time

template <typename T>
T max_val(T a, T b) {
    return (a > b) ? a : b;
}
// Usage: max_val(5, 10); // Instantiates max_val<int>
// Usage: max_val(5.0, 10.0); // Instantiates max_val<double>

// Cost: Binary size (code bloat)
// Performance: Faster function resolution, often inlined

// ---

// 3. Static Polymorphism (Compile-Time via CRTP)
// Achieves inheritance-like structure without dynamic dispatch

template <class Derived>
struct BaseCRTP {
    void operation() {
        // Static cast forces compile-time binding
        static_cast<Derived*>(this)->impl();
    }
};
struct ConcreteCRTP : BaseCRTP<ConcreteCRTP> {
    void impl() { /* Direct, fast call */ }
};
// Resolution: Compile-time (No vtable, direct branch)
// Memory: No vptr overhead
